import pandas as pd, numpy as np, os
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
cut=pd.Timestamp('2026-07-15')
px={}
for a in assets:
 p=f'../persistent/stock_data/{a}.csv'
 if os.path.exists(p):
  d=pd.read_csv(p,parse_dates=['date']).set_index('date').sort_index()['close'].loc[:cut]
  px[a]=d
P=pd.DataFrame(px).sort_index(); R=P.pct_change()
# Candidate: smoothed 5-day relative-dispersion reversal, rolling mean of 5d relative return over 3 observations
rel=R.rolling(5).sum(); cs=rel.sub(rel.median(axis=1),axis=0); raw=-cs
F=raw.rolling(3).mean()
# At date t signal only uses through t, forward starts t+1
fwd={h:R.shift(-1).rolling(h).sum().shift(-(h-1)) for h in [1,5,10]}
for h in [1,5,10]:
 vals=[]; dates=[]; ns=[]
 for dt in F.index:
  x=F.loc[dt]; y=fwd[h].loc[dt]; z=pd.concat([x,y],axis=1).dropna()
  if len(z)>=8:
   vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); dates.append(dt); ns.append(len(z))
 s=pd.Series(vals,index=dates).dropna(); print('h',h,'dates',len(s),'avgN',np.mean(ns),'coverage',np.mean(ns)/15,'IC',s.mean(),'ICIR',s.mean()/s.std(ddof=1),'hit',np.mean(s>0))
# turnover rank changes
rank=F.rank(axis=1,pct=True); print('turnover',rank.diff().abs().mean(axis=1).mean())
for lo,hi in [('2020','2022'),('2023','2024'),('2025','2026')]:
 s=[]
 for dt in F.loc[lo:hi].index:
  z=pd.concat([F.loc[dt],fwd[1].loc[dt]],axis=1).dropna()
  if len(z)>=8:s.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
 s=pd.Series(s).dropna();print(lo,'n',len(s),'IC',s.mean(),'ICIR',s.mean()/s.std(ddof=1) if len(s)>1 else np.nan)
print('last',F.dropna(how='all').index[-1])
# artifact
out=pd.DataFrame(F.loc['2020-01-01':].stack(),columns=['signal']);out.index.names=['date','symbol'];out.to_csv('scripts/miner_1_20260730_relative_dispersion_5d_signal.csv')

