def load(s):
 x=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).query('date<=@cut').sort_values('date').set_index('date'); return x

def make(h):
 out=[]
 for s in U:
  x=load(s); r=x.close.pct_change(); f=r.rolling(20,min_periods=15).sum()/(r.rolling(20,min_periods=15).std()*np.sqrt(20)+1e-12); y=x.close.shift(-h)/x.close-1
  out.append(pd.DataFrame({'date':x.index,'symbol':s,'signal':f,'fwd':y}))
