 regime=np.where(disp>threshold,-1.0,1.0)
 sig=(-a['r5'].div(a['vol']*np.sqrt(20))).mul(regime,axis=0)
 out=longf(sig,'signal'); prices=pd.concat([load(s).close.rename(s) for s in U],axis=1); fwd=prices.shift(-1).div(prices)-1
