 if d is not None and len(d):
  x=d[['date','close']].drop_duplicates('date');x['symbol']=s;rows.append(x)
p=pd.concat(rows);c=p.pivot(index='date',columns='symbol',values='close').sort_index().ffill()
r=c.pct_change(); vol=r.rolling(20,min_periods=15).std()*np.sqrt(252)
# medium-horizon risk-adjusted momentum, robustly cross-section demeaned and clipped
f=(c/c.shift(20)-1)/vol.replace(0,np.nan)
