import numpy as np,pandas as pd
from scipy.stats import spearmanr
from alphacrafter.sim.utils import get_stock_daily_data,get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
rows=[]
for s in U:
 d=get_stock_daily_data(s,3000)
 if d is None or len(d)<200: d=get_index_daily_data(s,3000)
 if d is not None and len(d):
  x=d[['date','close']].drop_duplicates('date'); x['symbol']=s; rows.append(x)
cl=pd.concat(rows).pivot(index='date',columns='symbol',values='close').sort_index().ffill(); r=cl.pct_change()
# Trend consistency: fraction of positive daily returns, weighted toward recent observations.
pos=(r>0).rolling(40,min_periods=30).mean()
# combine consistency with signed medium return, avoiding pure directionless quality
f=(pos*(cl.pct_change(40))).shift(1)
fut={h:cl.shift(-h)/cl-1 for h in [1,3,5,10]}
def ev(h,mask=None):
 qs=[];ns=[]
 for dt in cl.index:
  if mask is not None and not bool(mask.loc[dt]): continue
  z=pd.concat([f.loc[dt],fut[h].loc[dt]],axis=1).dropna()
  if len(z)>=8:
   q=spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic
   if np.isfinite(q): qs.append(q);ns.append(len(z))
 q=pd.Series(qs)
 return len(q),float(q.mean()),float(q.mean()/q.std(ddof=1)*np.sqrt(len(q))) if len(q)>1 else np.nan,float((q>0).mean()),float(np.mean(ns))
print('cutoff',cl.index.max().date(),'dates',len(cl),'instruments',len(cl.columns))
for h in [1,3,5,10]: print('horizon',h,ev(h))
for name,mask in [('2020-22',cl.index<'2023-01-01'),('2023-25',(cl.index>='2023-01-01')&(cl.index<'2026-01-01')),('2026+',cl.index>='2026-01-01'),('recent120',pd.Series(False,index=cl.index))]:
 if name=='recent120': mask.iloc[-120:]=True
 print('regime',name,ev(5,mask))
print('coverage',round(f.notna().mean().mean(),4),'turnover',round(f.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean(),4))
out=f.stack().rename('signal').reset_index(); out.columns=['date','symbol','signal']; out.to_csv('scripts/miner_1_20280210_trendconsistency40_signal.csv',index=False)

