import numpy as np,pandas as pd
from scipy.stats import spearmanr
from alphacrafter.sim.utils import get_stock_daily_data,get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
rows=[]
for s in U:
 d=get_stock_daily_data(s,3000)
 if d is None or len(d)<200: d=get_index_daily_data(s,3000)
 if d is not None and len(d):
  x=d[['date','close']].drop_duplicates('date'); x['symbol']=s; rows.append(x)
cl=pd.concat(rows).pivot(index='date',columns='symbol',values='close').sort_index().ffill()
r=cl.pct_change()
# Orthogonal relative-strength factor: asset's lagged 20-session return minus
# cross-sectional median 20-session return. This removes broad market direction.
ret20=cl.pct_change(20)
f=(ret20.sub(ret20.median(axis=1),axis=0)).shift(1)
res={h:[] for h in [1,3,5,10]}
for dt in cl.index:
 for h in res:
  z=pd.concat([f.loc[dt],cl.shift(-h).loc[dt]/cl.loc[dt]-1],axis=1).dropna()
  if len(z)>=8:
   q=spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic
   if np.isfinite(q): res[h].append(q)
for h,a in res.items():
 q=pd.Series(a); print('horizon',h,'obs',len(q),'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1)*np.sqrt(len(q)),'hit',(q>0).mean())
print('cutoff',cl.index.max().date(),'dates',len(cl),'instruments',len(cl.columns),'avgN',f.notna().sum(axis=1).mean(),'coverage',f.notna().mean().mean(),'turnover',f.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean())
for name,mask in [('2020-22',cl.index<'2023-01-01'),('2023-25',(cl.index>='2023-01-01')&(cl.index<'2026-01-01')),('2026+',cl.index>='2026-01-01')]:
 a=[]
 for dt in cl.index[mask]:
  z=pd.concat([f.loc[dt],cl.shift(-5).loc[dt]/cl.loc[dt]-1],axis=1).dropna()
  if len(z)>=8: a.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 print('regime',name,'n',len(a),'IC',np.mean(a) if a else np.nan,'ICIR',np.mean(a)/np.std(a,ddof=1)*np.sqrt(len(a)) if len(a)>1 else np.nan)
out=f.stack().rename('signal').reset_index(); out.columns=['date','symbol','signal']; out.to_csv('scripts/miner_1_20280601_relative_strength20_signal.csv',index=False)

import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
    for f in (get_index_daily_data,get_stock_daily_data):
        try:
            x=f(s,days=4000)
            if x is not None and len(x)>100: return x[['date','close']].copy()
        except Exception: pass
    return None
D={s:fetch(s) for s in U}; D={s:x for s,x in D.items() if x is not None}
print('instruments',len(D),[s for s in U if s not in D])
# aligned close panel
P=pd.concat([x.set_index('date').close.rename(s) for s,x in D.items()],axis=1).sort_index().ffill()
# factor: low realized volatility, lagged 20d; use daily log return std * sqrt20, negative
r=np.log(P).diff(); vol=r.rolling(20).std().shift(1)
f=-vol
rows=[]
for h in [1,3,5,10]:
  ic=[]; ns=[]; dates=[]
  fr=P.shift(-h)/P-1
  for dt in f.index:
    a=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
    if len(a)>=8:
      z=a.iloc[:,0].rank().corr(a.iloc[:,1].rank())
      if pd.notna(z): ic.append(z); ns.append(len(a)); dates.append(dt)
  q=pd.Series(ic,index=pd.to_datetime(dates)); print('H',h,'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1)*np.sqrt(len(q)),'hit',(q>0).mean(),'nobs',len(q),'avgN',np.mean(ns))
# turnover rank changes across adjacent dates
rr=f.rank(axis=1,pct=True); ch=(rr.diff().abs().mean(axis=1)>0.05).mean(); print('coverage',f.notna().mean().mean(),'turnover_proxy',ch)
# regimes for h10
h=10; fr=P.shift(-h)/P-1; vals=[]
for dt in f.index:
 a=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
 if len(a)>=8:
  z=a.iloc[:,0].rank().corr(a.iloc[:,1].rank())
  if pd.notna(z): vals.append((dt,z))
